<?php

namespace Tests\Unit\Services\Prediction;

use App\Services\Prediction\CandidateModelService;
use App\Services\Prediction\PredictionEngineV1;
use PHPUnit\Framework\TestCase;
use RuntimeException;

/**
 * P8-UI — CandidateModelService tests.
 * Pure unit tests: no DB, no HTTP, no Laravel container.
 * Requires tools/models/prediction_engine_no_e9.json and
 *           tools/models/prediction_engine_no_e9_no_e10.json
 * (generated by tools/scripts/generate_candidate_artifacts.py).
 *
 * Golden fixture: tests/Fixtures/Prediction/prediction_engine_v1_golden.json
 */
class CandidateModelServiceTest extends TestCase
{
    private const TOLERANCE_LAMBDA = 1e-10;
    private const TOLERANCE_PROB   = 1e-10;
    private const TOLERANCE_SUM    = 1e-8;
    private const GOLDEN_PATH      = __DIR__ . '/../../../Fixtures/Prediction/prediction_engine_v1_golden.json';
    private const MODELS_DIR       = __DIR__ . '/../../../../tools/models';

    private static array $golden = [];
    private CandidateModelService $service;

    public static function setUpBeforeClass(): void
    {
        parent::setUpBeforeClass();

        $artifactPath = realpath(self::MODELS_DIR . '/prediction_engine_v1.json')
            ?: self::MODELS_DIR . '/prediction_engine_v1.json';
        PredictionEngineV1::setArtifactPath($artifactPath);

        $dir = realpath(self::MODELS_DIR) ?: self::MODELS_DIR;
        CandidateModelService::setArtifactDir($dir);

        $json = file_get_contents(self::GOLDEN_PATH);
        self::$golden = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    }

    public static function tearDownAfterClass(): void
    {
        PredictionEngineV1::reset();
        CandidateModelService::reset();
        parent::tearDownAfterClass();
    }

    protected function setUp(): void
    {
        parent::setUp();
        $this->service = new CandidateModelService();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // A. FULL 59 parity with PredictionEngineV1
    // ─────────────────────────────────────────────────────────────────────────

    /** @test */
    public function test_A_full59_replicates_prediction_engine_v1(): void
    {
        foreach (self::$golden['cases'] as $case) {
            $features  = $case['features'];
            $reference = PredictionEngineV1::predict($features);
            $comparison = $this->service->compare($features);

            $full59 = $comparison['full59'];

            $this->assertEqualsWithDelta(
                $reference['lambda_home'],
                $full59['lambda_home'],
                self::TOLERANCE_LAMBDA,
                "match {$case['match_id']}: full59 lambda_home mismatch"
            );
            $this->assertEqualsWithDelta(
                $reference['lambda_away'],
                $full59['lambda_away'],
                self::TOLERANCE_LAMBDA,
                "match {$case['match_id']}: full59 lambda_away mismatch"
            );
            $this->assertEqualsWithDelta(
                $reference['probability_home'],
                $full59['probability_home'],
                self::TOLERANCE_PROB,
                "match {$case['match_id']}: full59 P(H) mismatch"
            );
            $this->assertEqualsWithDelta(
                $reference['probability_draw'],
                $full59['probability_draw'],
                self::TOLERANCE_PROB,
                "match {$case['match_id']}: full59 P(D) mismatch"
            );
            $this->assertEqualsWithDelta(
                $reference['probability_away'],
                $full59['probability_away'],
                self::TOLERANCE_PROB,
                "match {$case['match_id']}: full59 P(A) mismatch"
            );
        }

        fwrite(STDERR, sprintf("\n  [A] FULL 59 parity verified on %d cases\n", count(self::$golden['cases'])));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // B. P(H)+P(D)+P(A) = 1 for all three models
    // ─────────────────────────────────────────────────────────────────────────

    /** @test */
    public function test_B_all_models_probabilities_sum_to_one(): void
    {
        $slots = ['full59', 'no_e9', 'no_e9_no_e10'];

        foreach (self::$golden['cases'] as $case) {
            $comparison = $this->service->compare($case['features']);

            foreach ($slots as $slot) {
                $data = $comparison[$slot];
                if ($data === null) {
                    continue; // candidate artifact not available — skip slot
                }

                $sum = $data['probability_home'] + $data['probability_draw'] + $data['probability_away'];

                $this->assertEqualsWithDelta(
                    1.0,
                    $sum,
                    self::TOLERANCE_SUM,
                    "match {$case['match_id']}: slot={$slot} P sum={$sum}"
                );
            }
        }

        $noE9Available  = $comparison['no_e9_available']  ?? false;
        $noE10Available = $comparison['no_e10_available'] ?? false;
        fwrite(STDERR, sprintf(
            "\n  [B] P sum=1 verified — no_e9=%s  no_e9_no_e10=%s\n",
            $noE9Available ? 'OK' : 'SKIPPED(artifact missing)',
            $noE10Available ? 'OK' : 'SKIPPED(artifact missing)'
        ));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // C. compare() returns expected keys
    // ─────────────────────────────────────────────────────────────────────────

    /** @test */
    public function test_C_compare_returns_expected_structure(): void
    {
        $features = self::$golden['cases'][0]['features'];
        $result   = $this->service->compare($features);

        $this->assertArrayHasKey('full59',           $result);
        $this->assertArrayHasKey('no_e9',            $result);
        $this->assertArrayHasKey('no_e9_no_e10',     $result);
        $this->assertArrayHasKey('no_e9_available',  $result);
        $this->assertArrayHasKey('no_e10_available', $result);

        foreach (['lambda_home', 'lambda_away', 'probability_home', 'probability_draw', 'probability_away'] as $key) {
            $this->assertArrayHasKey($key, $result['full59'], "full59 missing key: {$key}");
        }

        $this->assertIsBool($result['no_e9_available']);
        $this->assertIsBool($result['no_e10_available']);
    }
}
